 LoadLibraryW(L"Msftedit.dll");INITCOMMONCONTROLSEX controls{sizeof controls,ICC_STANDARD_CLASSES};InitCommonControlsEx(&controls);auto store=std::make_shared<Store>(folder/"state");store->load();store->useWorkspace(std::string(64,'a'));store->settings.update({{"api",api},{"api_key","model-test-key"},{"auto_update",false}});auto before=store->settings;App app(store);auto parent=CreateWindowExW(0,L"STATIC",L"",0,0,0,1200,1000,nullptr,nullptr,GetModuleHandle(nullptr),nullptr);app.hwnd=parent;app.width=1200;app.height=900;app.accountProfile={{"account_id","model-owner"},{"role","safe"},{"model_management_supported",true}};app.welcome=false;app.setPage(14);
